// ─── HELPER FUNCTIONS ───────────────────────────────────────────────────────

// Get all cities for a specific country (country isolation)
export function getCitiesForCountry(countryId: string): FrenchCity[] {
  return FRENCH_CITIES.filter(c => c.countryId === countryId);
}

// Get all resources for a specific city
export function getResourcesForCity(cityId: string): FrenchCityResource[] {
  return FRENCH_CITY_RESOURCES.filter(r => r.cityId === cityId);
}

// Get resources for a city filtered by category
export function getResourcesForCityByCategory(cityId: string, category: FrenchCategory): FrenchCityResource[] {
  return FRENCH_CITY_RESOURCES.filter(r => r.cityId === cityId && r.category === category);
}

// Find the nearest city WITHIN a specific country (country isolation — critical)
// A French user will NEVER be matched to Casablanca.
const EARTH_RADIUS_KM = 6371;

export interface FrenchCityMatch {
  city: FrenchCity;
  distanceKm: number;
  isInServiceArea: boolean;
}

export function findNearestFrenchCity(lat: number, lng: number, countryId: string): FrenchCityMatch | null {
  const cities = getCitiesForCountry(countryId);
  if (cities.length === 0) return null;

  let nearest = cities[0];
  let minDist = Infinity;

  for (const city of cities) {
    const dist = haversineKm(lat, lng, city.lat, city.lng);
    if (dist < minDist) {
      minDist = dist;
      nearest = city;
    }
  }

  return {
    city: nearest,
    distanceKm: minDist,
    isInServiceArea: minDist <= nearest.metroRadiusKm,
  };
}

function haversineKm(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const toRad = (deg: number) => deg * (Math.PI / 180);
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return EARTH_RADIUS_KM * c;
}

// Map English category names to French category names (for cross-language matching)
export const ENGLISH_TO_FRENCH_CATEGORY: Record<string, FrenchCategory> = {
  "Housing Assistance": "Logement",
  "Food Assistance": "Aide alimentaire",
  "Healthcare": "Santé",
  "Legal Aid": "Aide juridique",
  "Employment": "Emploi",
  "Employment Services": "Emploi",
  "Mental Health": "Santé mentale",
  "Substance Use": "Addictions",
  "Senior Services": "Personnes âgées",
  "Senior Support": "Personnes âgées",
  "Veteran Services": "Personnes âgées", // closest equivalent
  "Veteran Support": "Personnes âgées",
};

// Get resources for a category in a city, accepting both English and French category names
export function getResourcesForCityByAnyCategory(cityId: string, category: string): FrenchCityResource[] {
  const frenchCategory = ENGLISH_TO_FRENCH_CATEGORY[category] ?? category as FrenchCategory;
  return getResourcesForCityByCategory(cityId, frenchCategory);
}
